/**
 * PWA assets — manifest, service worker and icons.
 *
 * These used to live only in public/ and were never committed, so a Docker build
 * that did not COPY public/ produced an image whose manifest, service worker and
 * icons were missing. Express then answered those paths with index.html at HTTP
 * 200 — a silent failure that passes a status check and breaks Add to Home
 * Screen. They are generated here from committed sources so public/ can be built
 * from scratch in any image.
 *
 * Run AFTER `vite build`, which writes public/index.html and public/assets/.
 */
const fs = require('fs');

/* ---------------------------------------------------------------------------
   PWA assets. These used to live only in public/ and were never committed, so
   a Docker build that did not COPY public/ produced an image whose manifest,
   service worker and icons were missing. Express then answered those paths with
   index.html at HTTP 200 — a silent failure that looks fine in a status check
   and breaks 'Add to Home Screen'. They are generated here from committed
   sources so public/ can be built from scratch in any image.
--------------------------------------------------------------------------- */
const MANIFEST = "{\n  \"name\": \"Hi-Klean Dental Billing\",\n  \"short_name\": \"Hi-Klean\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"browser\",\n  \"orientation\": \"any\",\n  \"background_color\": \"#0d2b33\",\n  \"theme_color\": \"#0d2b33\",\n  \"icons\": [\n    { \"src\": \"/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any maskable\" }\n  ]\n}\n";
const SW_JS = "/* App shell cached so the screen opens instantly on a phone.\n   Data is ALWAYS fetched live — nothing about a patient is stored on the device. */\nconst SHELL = 'hk-shell-v3';\nconst FILES = ['/', '/index.html', '/manifest.webmanifest', '/icon-192.png', '/icon-512.png'];\nself.addEventListener('install', e => {\n  e.waitUntil(caches.open(SHELL).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));\n});\nself.addEventListener('activate', e => {\n  e.waitUntil(caches.keys().then(k => Promise.all(k.filter(x => x !== SHELL).map(x => caches.delete(x)))).then(() => self.clients.claim()));\n});\nself.addEventListener('fetch', e => {\n  const url = new URL(e.request.url);\n  if (url.pathname.startsWith('/api/')) return;                  // never cache clinical data\n  if (e.request.method !== 'GET') return;\n  e.respondWith(\n    fetch(e.request).then(r => {\n      const copy = r.clone();\n      caches.open(SHELL).then(c => c.put(e.request, copy)).catch(() => {});\n      return r;\n    }).catch(() => caches.match(e.request).then(r => r || caches.match('/index.html')))\n  );\n});\n";
const ICON192 = "";
const ICON512 = "";
fs.mkdirSync('public', { recursive: true });
fs.writeFileSync('public/manifest.webmanifest', MANIFEST);
fs.writeFileSync('public/sw.js', SW_JS);
fs.writeFileSync('public/icon-192.png', Buffer.from(ICON192, 'base64'));
fs.writeFileSync('public/icon-512.png', Buffer.from(ICON512, 'base64'));
fs.writeFileSync('public/icon.png', Buffer.from(ICON192, 'base64'));
console.log('public/ assets: manifest, sw.js, icon-192, icon-512, icon');

